import { readFileSync } from "node:fs";
import { resolve } from "node:path";

// The dev logins generated by `make keycloak-realm` - test values of THIS app, never real ones.
const dir = resolve(process.cwd(), "..", "secrets", "keycloak");
const usersFile = process.env.AEOI_TEST_KEYCLOAK_USERS ?? resolve(dir, "users.txt");

type RealmUser = { email: string; enabled: boolean; realmRoles: string[] };

/** The n-th user with a role, in email order: the same user as `make kc-token ROLE= NTH=`. */
export function login(role: string, nth = 1): { email: string; password: string } {
  const realm = JSON.parse(readFileSync(resolve(dir, "aeoi-realm.json"), "utf8")) as { users: RealmUser[] };
  const emails = realm.users.filter((u) => u.enabled && u.realmRoles.includes(role)).map((u) => u.email).sort();
  const email = emails[nth - 1];
  if (!email) throw new Error(`no user #${nth} with role ${role}`);
  const line = readFileSync(usersFile, "utf8").split("\n").find((l) => l.startsWith(`${email} `));
  if (!line) throw new Error(`no login for ${email}`);
  return { email, password: line.slice(email.length + 1).trim() };
}
